import json
Q=[]
def q(n,e,a,c,tx=None): Q.append(dict(n=n,e=e,a=a,c=c,tx=tx))
# FÁCEIS
q(1,"Assinale a alternativa que contém apenas preposições.",["de, para, com, sem","e, mas, porém, logo","que, se, como, quando","muito, bem, já, ainda","o, a, os, as"],"De, para, com e sem são preposições essenciais. As demais listas trazem conjunções, advérbios ou artigos.")
q(1,"Em “A viatura da Guarda chegou”, a preposição “de” (em “da”) indica",["posse.","lugar.","tempo.","causa.","finalidade."],"A viatura pertence à Guarda.")
q(1,"Em “Abriu o portão com a chave reserva”, a preposição “com” indica",["instrumento.","companhia.","causa.","tempo.","oposição."],"A chave é o instrumento usado para abrir.")
q(1,"Em “Fez a ronda com o parceiro”, a preposição “com” indica",["companhia.","instrumento.","modo.","causa.","lugar."],"O parceiro acompanhou a ronda.")
q(1,"Em “O suspeito foi detido pelo guarda”, a expressão “pelo guarda” é introduzida pela preposição “por” e indica",["o agente da ação na voz passiva.","o lugar da ação.","a finalidade da ação.","o tempo da ação.","a causa da ação."],"Na voz passiva, “por” introduz quem pratica a ação: o guarda deteve o suspeito.")
q(1,"Em “A equipe ficou no local para preservar a cena”, a preposição “para” indica",["finalidade.","causa.","lugar.","tempo.","oposição."],"Para preservar = a fim de preservar.")
q(1,"Assinale a conjunção adversativa.",["porém","porque","quando","embora","se"],"Porém indica oposição. Porque é causal; quando, temporal; embora, concessiva; se, condicional.")
q(1,"Em “Estudou e passou no concurso”, a conjunção “e” indica",["adição.","oposição.","conclusão.","explicação.","alternância."],"Soma dois fatos que combinam.")
q(1,"Em “Ou você estuda, ou desiste da vaga”, o par “ou... ou” expressa",["alternância.","adição.","causa.","conclusão.","concessão."],"Uma possibilidade exclui a outra.")
q(1,"Em “A rua estava escura; portanto, a ronda foi reforçada”, “portanto” indica",["conclusão.","oposição.","causa.","tempo.","condição."],"O reforço é a conclusão tirada da rua escura.")
q(1,"Em “A ronda foi adiada porque choveu”, “porque” indica",["causa.","consequência.","condição.","finalidade.","concessão."],"A chuva é o motivo do adiamento.")
q(1,"Em “Embora estivesse cansado, o guarda terminou a ronda”, “embora” indica",["concessão.","causa.","condição.","conclusão.","tempo."],"O cansaço é um obstáculo que não impediu a ronda.")
q(1,"Em “Se chover, a feira será cancelada”, “se” indica",["condição.","causa.","tempo.","concessão.","finalidade."],"O cancelamento depende da chuva.")
q(1,"Em “Quando a viatura chegou, o suspeito fugiu”, “quando” indica",["tempo.","causa.","condição.","conformidade.","proporção."],"Marca o momento da fuga.")
q(1,"Em “O relatório foi feito conforme o manual”, “conforme” indica",["conformidade.","comparação.","condição.","causa.","tempo."],"Conforme = de acordo com.")
q(1,"Em “Ele correu tanto que ficou sem fôlego”, a construção “tanto... que” indica",["consequência.","causa.","finalidade.","comparação.","concessão."],"Ficar sem fôlego é o resultado de correr tanto.")
q(1,"A palavra “pelo”, em “Passou pelo centro”, é formada por",["preposição “por” + artigo “o”.","preposição “para” + artigo “o”.","pronome + artigo.","conjunção + artigo.","advérbio + artigo."],"Por + o = pelo, uma contração.")
q(1,"Em “Passou a noite sob custódia”, a preposição “sob” indica",["posição inferior, sujeição.","posição superior.","assunto.","companhia.","oposição."],"Sob = debaixo de, sujeito a. Não confunda com sobre.")
q(1,"Em “Falaram sobre o caso na reunião”, “sobre” indica",["assunto.","posição inferior.","tempo.","companhia.","causa."],"Sobre o caso = a respeito do caso.")
q(1,"No primeiro parágrafo, “porque” introduz",["a causa da medida adotada.","a consequência da medida.","uma condição para a medida.","uma oposição à medida.","a finalidade da medida."],"Os furtos registrados explicam por que a Guarda reforçou a feira.",tx="tl")
# MÉDIAS
q(2,"Em “Estudou muito e não passou”, a conjunção “e” tem valor",["adversativo, equivalendo a “mas”.","aditivo.","conclusivo.","explicativo.","alternativo."],"Os fatos se chocam: estudou muito, mas não passou.")
q(2,"Em “Leve o guarda-chuva, pois vai chover”, “pois” é",["explicativo.","conclusivo.","adversativo.","alternativo.","aditivo."],"Antes do verbo, justifica a ordem dada.")
q(2,"Em “Choveu muito; a ronda, pois, foi adiada”, “pois” é",["conclusivo, equivalendo a “portanto”.","explicativo.","causal, equivalendo a “porque”.","adversativo.","aditivo."],"Depois do verbo e entre vírgulas, “pois” conclui.")
q(2,"Em “Como estava chovendo, a ronda foi adiada”, “como” indica",["causa.","comparação.","conformidade.","modo.","tempo."],"No início da frase, “como” = já que.")
q(2,"Em “Fiz o relatório como o chefe pediu”, “como” indica",["conformidade.","causa.","comparação.","condição.","tempo."],"Como = conforme.")
q(2,"Em “Ele é forte como um touro”, “como” indica",["comparação.","causa.","conformidade.","condição.","finalidade."],"Compara a força dele à de um touro.")
q(2,"Em “Você entra, desde que apresente o crachá”, “desde que” indica",["condição.","tempo.","causa.","concessão.","finalidade."],"Com subjuntivo (apresente), desde que = contanto que.")
q(2,"Em “Desde que entrou na Guarda, ele trabalha à noite”, “desde que” indica",["tempo.","condição.","causa.","conformidade.","finalidade."],"Com indicativo (entrou), marca o ponto de partida no tempo.")
q(2,"Em “À medida que a noite avançava, o movimento diminuía”, a locução destacada indica",["proporção.","causa.","condição.","concessão.","finalidade."],"Um fato varia junto com o outro.")
q(2,"Em “Fale baixo para que o bebê não acorde”, “para que” indica",["finalidade.","causa.","consequência.","condição.","tempo."],"Indica o objetivo de falar baixo.")
q(2,"Assinale a frase de acordo com a norma-padrão.",["Chegou a hora de o guarda sair.","Chegou a hora do guarda sair.","Está na hora dele assinar o termo.","Apesar do motorista ter parado, foi multado.","Antes dos agentes chegarem, a rua foi fechada."],"Quando o termo é sujeito do infinitivo, a preposição não se junta a ele: de o guarda sair.")
q(2,"Segundo a norma-padrão, a expressão “ao invés de” indica",["oposição, ideia contrária.","simples substituição, troca.","causa.","finalidade.","tempo."],"Ao invés de = ao contrário de. Para troca, usa-se em vez de.")
q(2,"Assinale a frase em que “ao invés de” está empregado de acordo com a norma-padrão.",["Ao invés de subir, o preço desceu.","Ao invés de café, pediu chá.","Ao invés do guarda André, veio o guarda Bruno.","Ao invés de ônibus, foi de táxi.","Ao invés de caneta, usou lápis."],"Só em (A) há ideias opostas (subir e descer). Nas demais, há simples troca: em vez de.")
q(2,"Em “O carro foi de encontro ao poste”, a expressão indica",["choque, colisão.","a favor, na direção de.","finalidade.","proximidade sem contato.","concordância."],"De encontro a = contra, em choque com.")
q(2,"Em “A proposta vem ao encontro do que pedimos”, a expressão indica",["concordância com o que se deseja.","oposição.","choque.","causa.","tempo."],"Ao encontro de = em direção a, a favor de.")
q(2,"Assinale a reescrita que mantém o sentido de “Embora estivesse cansado, continuou a ronda”.",["Estava cansado, mas continuou a ronda.","Estava cansado, porque continuou a ronda.","Se estava cansado, continuou a ronda.","Estava cansado, portanto continuou a ronda.","Estava cansado, ou continuou a ronda."],"A concessão (embora) pode virar oposição (mas), com o verbo ajustado ao indicativo.")
q(2,"Em “Caso a experiência dê certo, o modelo será ampliado”, a oração destacada pode ser reescrita, sem alteração de sentido, como",["Se a experiência der certo","Embora a experiência dê certo","Porque a experiência deu certo","Para que a experiência dê certo","Assim que a experiência deu certo"],"Caso e se são condicionais; com “se”, o verbo vai ao futuro do subjuntivo (der).")
q(2,"Assinale a alternativa em que “que” é conjunção integrante.",["O comandante disse que a escala mudou.","O guarda que chegou é novo.","Era tão tarde que a feira fechou.","Mais vale prevenir que remediar.","Que dia difícil!"],"A integrante introduz a oração que completa “disse”: disse isso. Em (B) é pronome relativo; em (C), consecutiva; em (D), comparativa; em (E), exclamativo.")
q(2,"Em “Não só registrou a ocorrência, mas também ouviu as testemunhas”, o par “não só... mas também” indica",["adição.","oposição.","alternância.","conclusão.","causa."],"Soma duas ações. Aqui “mas” não opõe.")
q(2,"No primeiro parágrafo, “Contudo” estabelece relação de",["oposição em relação à ideia anterior.","conclusão.","causa.","tempo.","adição."],"Contradiz a crença de que só os grandes crimes importam.",tx="tm")
# DIFÍCEIS
q(3,"No segundo parágrafo, “para que possam atender rapidamente qualquer chamado” expressa",["a finalidade de os agentes circularem a pé.","a causa de os agentes circularem a pé.","a consequência do fechamento da feira.","uma condição para a feira abrir.","uma oposição à presença da Guarda."],"Para que = a fim de que: indica o objetivo.",tx="tl")
q(3,"No segundo parágrafo, a frase iniciada por “Embora” poderia ser reescrita, sem alteração de sentido, como",["Ainda que a feira tenha poucas entradas, todas terão um ponto de apoio com rádio.","Porque a feira tem poucas entradas, todas terão um ponto de apoio com rádio.","Se a feira tiver poucas entradas, todas terão um ponto de apoio com rádio.","Como a feira tem poucas entradas, todas terão um ponto de apoio com rádio.","Para que a feira tenha poucas entradas, todas terão um ponto de apoio com rádio."],"Embora e ainda que são concessivas. As demais criam causa, condição ou finalidade.",tx="tl")
q(3,"No último parágrafo, “mas” e “Caso” expressam, respectivamente,",["oposição e condição.","adição e tempo.","conclusão e causa.","oposição e causa.","explicação e condição."],"Mas: contraste com a aprovação. Caso: condição para levar o modelo a outras feiras.",tx="tl")
q(3,"Em “os agentes circularão a pé pelos corredores”, a preposição “por” (em “pelos”) indica",["lugar por onde se passa.","agente da passiva.","causa.","finalidade.","preço."],"Os corredores são o percurso dos agentes.",tx="tl")
q(3,"No segundo parágrafo, “à medida que se acumulam” indica",["proporção.","finalidade.","concessão.","condição.","comparação."],"Quanto mais detalhes se acumulam, mais a ideia de abandono se transmite.",tx="tm")
q(3,"No segundo parágrafo, “Por isso” introduz",["uma conclusão a partir do que foi dito antes.","uma causa do que foi dito antes.","uma oposição ao que foi dito antes.","uma condição para o que vem depois.","um exemplo do que foi dito antes."],"Por isso = portanto: conclui do que veio antes.",tx="tm")
q(3,"No último parágrafo, “portanto”, entre vírgulas, poderia ser substituído, sem alteração de sentido, por",["por conseguinte","no entanto","porque","embora","caso"],"Portanto e por conseguinte são conclusivas.",tx="tm")
q(3,"Assinale a alternativa em que “desde que” tem valor condicional.",["Pode estacionar aqui, desde que não ultrapasse duas horas.","Desde que chegou, não parou de trabalhar.","Desde que a praça foi reformada, o movimento cresceu.","Ele mora no bairro desde que nasceu.","Desde que o turno começou, houve três chamados."],"Com subjuntivo (ultrapasse), é condição. Nas demais, com indicativo, é tempo.")
q(3,"Assinale a alternativa em que “como” tem valor causal.",["Como o sinal estava fechado, o motorista parou.","Agiu como o protocolo determina.","Ela grita como uma sirene.","Como combinado, a equipe chegou às 22h.","Fez tudo como o chefe mandou."],"Em (A), como = já que. Nas demais: conformidade (B, D, E) e comparação (C).")
q(3,"Em “Ele tanto estudou que passou”, a oração “que passou” expressa",["consequência.","causa.","finalidade.","comparação.","condição."],"Passar é o resultado de ter estudado tanto.")
q(3,"Assinale a alternativa em que a preposição “de” indica causa.",["Tremia de frio na madrugada.","Saiu de casa cedo.","A grade é de ferro.","Chegou de moto.","Falaram do caso."],"Tremia por causa do frio. Nas demais: origem, matéria, meio e assunto.")
q(3,"Assinale a alternativa em que a preposição “por” indica causa.",["Foi preso por furto.","Passou pela praça.","Foi detido pelo guarda.","Vendeu a moto por cinco mil reais.","Trabalhou ali por dois anos."],"Preso por causa de furto. Nas demais: lugar por onde, agente da passiva, preço e duração.")
q(3,"Em qual alternativa a expressão com “sem” tem valor de condição?",["Sem autorização, ninguém entra no prédio.","Saiu sem o celular.","Chegou sem a farda.","Ficou sem bateria.","Escreveu sem erros."],"Em (A), equivale a “se não houver autorização”. Nas demais, “sem” indica ausência.")
q(3,"Assinale a alternativa em que “mas” NÃO tem valor adversativo.",["Não só patrulhou a praça, mas também orientou os moradores.","Correu, mas não alcançou o ônibus.","A feira é pequena, mas movimentada.","Chamou a central, mas ninguém atendeu.","Queria ir, mas estava de plantão."],"No par “não só... mas também”, há adição.")
q(3,"Em “Estude, que a prova está chegando”, a palavra “que” é conjunção",["explicativa, equivalendo a “pois”.","integrante.","consecutiva.","comparativa.","relativa."],"Depois de uma ordem, o “que” justifica: estude, pois a prova está chegando.")
q(3,"Assinale a alternativa que substitui o conectivo de “Ele foi promovido, visto que tinha bom desempenho” sem alterar o sentido.",["uma vez que","embora","a fim de que","contanto que","à medida que"],"Visto que e uma vez que são causais.")
q(3,"Assinale a alternativa em que a troca do conectivo ALTERA o sentido da frase.",["“A ronda continuou, embora chovesse” / “A ronda continuou, porque chovia”","“Saiu cedo para que chegasse a tempo” / “Saiu cedo a fim de que chegasse a tempo”","“Se houver chuva, a feira será cancelada” / “Caso haja chuva, a feira será cancelada”","“Fez conforme o manual” / “Fez segundo o manual”","“Choveu; logo, a ronda atrasou” / “Choveu; portanto, a ronda atrasou”"],"Embora (concessão) virou porque (causa). Nas demais, os conectivos são do mesmo tipo.")
q(3,"Em “Quando a sirene tocou, os comerciantes fecharam as portas, mas alguns permaneceram na calçada”, “quando” e “mas” indicam, respectivamente,",["tempo e oposição.","causa e adição.","condição e conclusão.","tempo e conclusão.","proporção e oposição."],"Quando marca o momento; mas opõe os que ficaram na calçada.")
q(3,"Assinale a afirmação INCORRETA.",["A preposição liga orações coordenadas entre si.","A conjunção pode ligar orações.","Locuções como “apesar de” e “a fim de” funcionam como preposição.","A mesma conjunção pode ter sentidos diferentes conforme o contexto.","“Pois” depois do verbo, entre vírgulas, tem valor conclusivo."],"Quem liga orações coordenadas são as conjunções coordenativas; a preposição liga termos.")
q(3,"Assinale a alternativa INCORRETA quanto ao sentido da preposição “a”.",["Em “Saiu a pé”, indica tempo.","Em “Chegou às 22h”, indica tempo.","Em “Foi a Campinas”, indica destino.","Em “Ficou a dois quilômetros do posto”, indica distância.","Em “Vendeu a prazo”, indica modo."],"Em “a pé”, a preposição indica modo ou meio, não tempo.")
assert len(Q)==60
from collections import Counter; print(Counter(x['n'] for x in Q))
for x in Q: assert len(x['a'])==5 and len(set(x['a']))==5, x['e']
L=['{id:"p8-%02d",n:%d,'%(i,x['n'])+('tx:"%s",'%x['tx'] if x['tx'] else '')+'e:%s,a:%s,c:%s}'%(json.dumps(x['e'],ensure_ascii=False),json.dumps(x['a'],ensure_ascii=False),json.dumps(x['c'],ensure_ascii=False)) for i,x in enumerate(Q,1)]
open('banco.js','w').write('BANCO["pt-8"] = [\n'+',\n'.join(L)+'\n];')
tl="<strong>Feira noturna terá reforço na segurança</strong><br><br>A partir da próxima sexta-feira, a feira noturna do centro contará com equipes da Guarda Municipal. A medida foi adotada porque os comerciantes registraram, nos últimos meses, uma série de furtos de celulares entre os frequentadores.<br><br>Segundo a coordenação da Guarda, os agentes circularão a pé pelos corredores, para que possam atender rapidamente qualquer chamado. Embora a feira tenha poucas entradas, todas terão um ponto de apoio com rádio.<br><br>Os feirantes aprovaram a iniciativa, mas pedem também melhor iluminação nas ruas próximas. Caso a experiência dê certo, o modelo poderá ser levado a outras feiras da cidade."
tm="<strong>Atenção ao que é pequeno</strong><br><br>Muitos acreditam que só os grandes crimes merecem preocupação. Contudo, quem trabalha nas ruas sabe que, quando pequenas desordens são toleradas, o ambiente se degrada e outros problemas aparecem.<br><br>Uma lixeira quebrada ou uma lâmpada apagada parecem detalhes. Mas, à medida que se acumulam, transmitem a ideia de que ninguém cuida do lugar, e quem pretende cometer um delito se sente mais à vontade. Por isso, a manutenção do espaço público não é apenas uma questão estética.<br><br>Isso não significa punir com rigor cada pequena falha, e sim agir cedo. Cuidar do que é pequeno, portanto, é também uma forma de prevenção."
open('textos.js','w').write(',\ntl: '+json.dumps(tl,ensure_ascii=False)+',\ntm: '+json.dumps(tm,ensure_ascii=False))
